import {buildings,places,distance,formatDistance,nearby} from './data.js';
import {icon,fillIcons,towerArt} from './graphics.js';
const $=id=>document.getElementById(id);
const reduced=matchMedia('(prefers-reduced-motion: reduce)').matches;
let map,selected=null,selectedPlace=null,filter='all',satellite=true,night=false,is3d=true,ready=false,tourTimer=null,tourIndex=0,toastTimer;
const markers=[];const vectorTheme=[];const home={center:[-48.6048,-27.1158],zoom:13.0,pitch:40,bearing:-24};
fillIcons();
$('buildingCards').innerHTML=buildings.map(b=>`<button class="building-card" data-building="${b.id}" aria-label="Explorar ${b.name}"><span class="building-art">${towerArt(b)}</span><span class="card-num">${b.number}</span><span class="card-info"><small>${b.region}</small><strong>${b.name}</strong><span>Maquete de demonstração</span></span><span class="card-arrow">↗</span></button>`).join('');
$('placesList').innerHTML='<h3>Lugares para descobrir</h3>'+places.map(p=>`<button data-place="${p.id}">${icon(p.icon)}<span>${p.name}</span><span>↗</span></button>`).join('');
function toast(s){$('toast').textContent=s;$('toast').hidden=false;clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('toast').hidden=true,4200);}
function fitPadding(){return innerWidth<761?{top:125,right:95,bottom:innerHeight*.54,left:70}:{top:110,right:110,bottom:230,left:350};}
function feature(geometry,properties={}){return{type:'Feature',geometry,properties};}
function fc(features=[]){return{type:'FeatureCollection',features};}
function rect(b,w,d,base,height,color,shift=0){const dx=w/2/(111320*Math.cos(b.coords[1]*Math.PI/180)),dy=d/2/111320;const x=b.coords[0]+shift/100000,y=b.coords[1];return feature({type:'Polygon',coordinates:[[[x-dx,y-dy],[x+dx,y-dy],[x+dx,y+dy],[x-dx,y+dy],[x-dx,y-dy]]]},{id:b.id,base,height,color});}
function buildingsGeo(){return fc(buildings.flatMap(b=>{const out=[rect(b,44,36,0,9,'#d5d7c3'),rect(b,30,23,9,b.height,'#457b87')];for(let n=0;n<b.floors;n++){const y=9+n*(b.height-9)/b.floors;out.push(rect(b,34+b.shape,26,y,y+.65,b.color,b.shape===2?Math.sin(n*.4)*1.5:0));}out.push(rect(b,28,20,b.height,b.height+3,b.color));return out;}));}
async function init(){try{
 const style=await fetch('map-style.json').then(r=>{if(!r.ok)throw Error('style');return r.json()});
 style.sources.satellite={type:'raster',tiles:['https://server.arcgisonline.com/ArcGIS/rest/services/World_Imagery/MapServer/tile/{z}/{y}/{x}'],tileSize:256,maxzoom:19,attribution:'Imagery © Esri, Vantor, Earthstar Geographics, GIS User Community'};
 style.layers.forEach(l=>{if(l.type==='symbol'){l.layout={...l.layout,visibility:'none'};}if(l.id==='building-3d'){l.paint['fill-extrusion-opacity']=.65;l.paint['fill-extrusion-color']='#c4cebc';}});
 style.layers.forEach(l=>{for(const key of ['background-color','fill-color','line-color','fill-extrusion-color','text-color','text-halo-color']){if(l.paint?.[key]!==undefined)vectorTheme.push({id:l.id,key,value:l.paint[key],water:(l['source-layer']||'').includes('water'),green:/park|wood|grass|forest|landcover/.test(l.id)});}});
 const index=style.layers.findIndex(l=>l.id==='building-3d');
 style.layers.splice(index<0?style.layers.length:index,0,{id:'satellite',type:'raster',source:'satellite',paint:{'raster-saturation':-.1,'raster-contrast':.02,'raster-brightness-max':1}});
 map=new maplibregl.Map({container:'map',style,...home,maxZoom:19,minZoom:10.5,maxPitch:70,attributionControl:false,antialias:true,canvasContextAttributes:{antialias:true},maxBounds:[[-48.73,-27.23],[-48.49,-27.01]]});
 map.addControl(new maplibregl.AttributionControl({compact:true}),'bottom-right');map.addControl(new maplibregl.ScaleControl({maxWidth:90,unit:'metric'}),'bottom-left');
 map.on('load',()=>{ready=true;addContent();overview(0);$('loading').classList.add('finished');setTimeout(()=>$('loading').hidden=true,700);handleHash();});
 map.on('zoom',()=>document.body.classList.toggle('map-close',map.getZoom()>14.4));
 map.on('rotate',()=>$('compassNeedle').style.transform=`rotate(${-map.getBearing()}deg)`);
 map.on('error',e=>{console.warn('Map resource unavailable:',e.error?.message);});
 setTimeout(()=>{if(!ready){$('loading').classList.add('finished');toast('O mapa está demorando para carregar. Verifique a conexão com a internet.');}},15000);
 }catch(e){$('loading').innerHTML='<span class="loader-logo">itapema<span>vista</span></span><p>Não foi possível carregar o mapa.</p><button class="pill" onclick="location.reload()">Tentar novamente</button>';console.error(e);}}
function addContent(){
 map.addLayer({id:'coastal-water',type:'fill',source:'openmaptiles','source-layer':'water',paint:{'fill-color':'#377f89','fill-opacity':.82}},'building-3d');
 map.addSource('demo-buildings',{type:'geojson',data:buildingsGeo()});
 map.addLayer({id:'demo-towers',type:'fill-extrusion',source:'demo-buildings',paint:{'fill-extrusion-color':['get','color'],'fill-extrusion-height':['get','height'],'fill-extrusion-base':['get','base'],'fill-extrusion-opacity':1}});
 map.addSource('connection',{type:'geojson',data:fc()});
 map.addLayer({id:'connection-glow',type:'line',source:'connection',paint:{'line-color':'#d9e8b3','line-width':6,'line-opacity':.14}});
 map.addLayer({id:'connection-line',type:'line',source:'connection',paint:{'line-color':'#e4edbf','line-width':2,'line-dasharray':[2,2],'line-opacity':.9}});
 [...buildings.map(b=>({...b,kind:'property'})),...places.map(p=>({...p,kind:'place'}))].forEach(item=>{
  const el=document.createElement('button');el.className=`map-marker ${item.kind}`;el.style.zIndex=item.kind==='property'?'3':'2';el.setAttribute('aria-label',item.kind==='property'?`Explorar ${item.name}`:`Ver ${item.name}`);
  el.innerHTML=`<span class="marker-title">${item.name}</span><span class="pin">${item.number||icon(item.icon)}</span><span class="stem"></span>`;
  el.addEventListener('click',e=>{e.stopPropagation();item.kind==='property'?selectBuilding(item.id):selectPlace(item.id);});
  const marker=new maplibregl.Marker({element:el,anchor:'bottom'}).setLngLat(item.coords).addTo(map);markers.push({item,el,marker});
 });
 map.on('click','demo-towers',e=>{if(e.features?.[0])selectBuilding(e.features[0].properties.id)});
 map.on('mouseenter','demo-towers',()=>map.getCanvas().style.cursor='pointer');map.on('mouseleave','demo-towers',()=>map.getCanvas().style.cursor='');
}
function selectBuilding(id,fromTour=false){if(!ready){toast('O mapa está carregando…');return;}if(!fromTour)stopTour();selected=buildings.find(b=>b.id===id);selectedPlace=null;if(!selected)return;
 $('intro').hidden=true;$('placesList').hidden=true;$('detail').hidden=false;document.body.classList.add('detail-open');
 filter='all';updateFilter();renderBuilding();highlight();setLine();history.replaceState(null,'',`#${id}`);
 const mobile=innerWidth<761;
 map.flyTo({center:selected.coords,zoom:16.8,pitch:is3d?59:0,bearing:-25,duration:reduced?0:1800,retainPadding:false,padding:mobile?{top:80,right:20,bottom:innerHeight*.45,left:15}:{top:110,right:100,bottom:220,left:350}});
}
function renderBuilding(){const b=selected;$('detail').innerHTML=`<div class="detail-inner"><div class="detail-top"><button class="back-button" data-action="back">${icon('arrow')} A cidade</button><span class="type-chip">DEMONSTRAÇÃO ${b.number}</span></div><h2>${b.name}</h2><div class="detail-region">${icon('pin')}${b.region} · Itapema</div><div class="detail-preview">${towerArt(b)}<span>ARQUITETURA<br>CONCEITUAL</span><span class="preview-3d">3D</span></div><button class="primary" data-action="viewer">${icon('cube')} Explorar maquete 3D <span class="arrow">↗</span></button><p>${b.description}</p><div class="detail-subtitle"><h3>O melhor de Itapema, por perto</h3>${icon('route')}</div><div class="distance-hint">Distâncias aproximadas em linha reta.<br>Selecione um lugar para visualizar a conexão.</div><div class="distance-list">${nearby(b).map(p=>`<div class="distance-row" data-row="${p.id}"><button class="distance-select" data-distance="${p.id}"><span class="row-icon">${icon(p.icon)}</span><span class="row-name">${p.name}<small>${p.category}</small></span><strong>${formatDistance(p.distance)}</strong></button><div class="route-links" hidden><a href="https://www.google.com/maps/dir/?api=1&origin=${b.coords[1]},${b.coords[0]}&destination=${p.coords[1]},${p.coords[0]}&travelmode=driving" target="_blank" rel="noopener">${icon('external')} Traçar rota</a><a href="${p.source}" target="_blank" rel="noopener">Sobre o lugar ↗</a></div></div>`).join('')}</div><p class="distance-hint">Prédio e terreno fictícios. Referências para teste.</p></div>`;$('detail').scrollTop=0;}
function connectPlace(id){if(!selected)return;selectedPlace=places.find(p=>p.id===id);if(!selectedPlace)return;
 $('detail').querySelectorAll('[data-row]').forEach(row=>{const active=row.dataset.row===id;row.classList.toggle('selected',active);row.querySelector('.route-links').hidden=!active});
 setLine();highlight();const bounds=new maplibregl.LngLatBounds();bounds.extend(selected.coords).extend(selectedPlace.coords);
 map.setPadding({top:0,right:0,bottom:0,left:0});map.fitBounds(bounds,{retainPadding:false,padding:fitPadding(),maxZoom:16,pitch:is3d?40:0,bearing:0,duration:reduced?0:1300});
}
function setLine(){if(!ready)return;map.getSource('connection').setData(selected&&selectedPlace?fc([feature({type:'LineString',coordinates:[selected.coords,selectedPlace.coords]})]):fc());}
function selectPlace(id){if(!ready){toast('O mapa está carregando…');return;}stopTour();selected=null;selectedPlace=places.find(p=>p.id===id);if(!selectedPlace)return;const p=selectedPlace;
 $('intro').hidden=true;$('placesList').hidden=true;$('detail').hidden=false;document.body.classList.add('detail-open');filter='all';updateFilter();setLine();highlight();history.replaceState(null,'',`#${id}`);
 const nearest=buildings.map(b=>({...b,d:distance(b.coords,p.coords)})).sort((a,b)=>a.d-b.d);
 $('detail').innerHTML=`<div class="detail-inner"><div class="detail-top"><button class="back-button" data-action="back">${icon('arrow')} A cidade</button><span class="type-chip">${p.category.toUpperCase()}</span></div><h2>${p.name}</h2><div class="detail-region">${icon('pin')}Itapema · Santa Catarina</div><div class="place-visual">${icon(p.icon)}</div><p>${p.description}</p><a class="primary" style="text-decoration:none" href="https://www.google.com/maps/search/?api=1&query=${p.coords[1]},${p.coords[0]}" target="_blank" rel="noopener">${icon('external')} Abrir no Google Maps</a><div class="detail-subtitle"><h3>Distância dos empreendimentos</h3></div><div class="distance-hint">Valores aproximados em linha reta.</div><div class="distance-list">${nearest.map(b=>`<div class="distance-row"><button class="distance-select" data-building="${b.id}" data-connect="${p.id}"><span class="row-icon">${b.number}</span><span class="row-name">${b.name}<small>${b.region}</small></span><strong>${formatDistance(b.d)}</strong></button></div>`).join('')}</div><p class="distance-hint"><a href="${p.source}" target="_blank" rel="noopener">Consultar fonte do local ↗</a></p></div>`;$('detail').scrollTop=0;
 map.flyTo({center:p.coords,zoom:16.2,pitch:is3d?50:0,bearing:-25,duration:reduced?0:1700,retainPadding:false,padding:fitPadding()});
}
function highlight(){markers.forEach(({item,el})=>el.classList.toggle('active',item.id===selected?.id||item.id===selectedPlace?.id));document.querySelectorAll('.building-card').forEach(el=>el.classList.toggle('selected',el.dataset.building===selected?.id));}
function updateFilter(){document.querySelectorAll('[data-filter]').forEach(b=>b.classList.toggle('active',b.dataset.filter===filter));markers.forEach(({item,el})=>el.style.display=(filter==='buildings'&&item.kind!=='property')||(filter==='places'&&item.kind!=='place')?'none':'');if(ready)map.setLayoutProperty('demo-towers','visibility',filter==='places'?'none':'visible');}
function reset(){stopTour();selected=null;selectedPlace=null;$('detail').hidden=true;$('intro').hidden=filter==='places';$('placesList').hidden=filter!=='places';document.body.classList.remove('detail-open');highlight();setLine();history.replaceState(null,'',location.pathname+location.search);if(ready)overview(reduced?0:1600);}
function overview(duration=0){const bounds=new maplibregl.LngLatBounds();[...buildings,...places].forEach(p=>bounds.extend(p.coords));map.setPadding({top:0,right:0,bottom:0,left:0});map.fitBounds(bounds,{retainPadding:false,padding:innerWidth<761?{top:320,right:73,bottom:215,left:25}:{top:150,right:130,bottom:240,left:330},bearing:home.bearing,pitch:is3d?home.pitch:0,maxZoom:13.5,duration});}
function stopTour(){clearTimeout(tourTimer);tourTimer=null;$('tourStatus').hidden=true;document.body.classList.remove('touring');$('tourButton').querySelector('span:nth-child(2)').textContent='Fazer um passeio';}
function startTour(){if(!ready)return;stopTour();tourIndex=0;document.body.classList.add('touring');$('tourStatus').hidden=false;const visit=()=>{if(tourIndex>=buildings.length){stopTour();toast('Passeio completo. Continue explorando os lugares no mapa.');return;}const b=buildings[tourIndex];selectBuilding(b.id,true);$('tourLabel').textContent=`${tourIndex+1} / 4 · ${b.name}`;tourIndex++;tourTimer=setTimeout(visit,7000);};visit();}
async function openViewer(){if(!selected)return;stopTour();const b=selected;const trigger=document.activeElement;$('viewerName').textContent=b.name;$('viewerRegion').textContent=`${b.region} · ${b.floors} pavimentos ilustrativos`;$('viewerDialog').querySelector('.viewer-bottom>span').innerHTML=icon('drag')+(innerWidth<761?'Arraste para girar · pinça para aproximar':'Arraste para girar · use a rolagem para aproximar');$('viewerDialog').showModal();$('modelCanvas').innerHTML='<div style="display:grid;place-items:center;height:100%;font-size:12px;color:#c8d8c9">Preparando a maquete…</div>';
 try{const {createViewer}=await import('./viewer.js');if(!$('viewerDialog').open)return;const viewer=createViewer($('modelCanvas'),b);$('autoRotate').classList.toggle('active',!reduced);$('autoRotate').setAttribute('aria-pressed',String(!reduced));$('autoRotate').onclick=()=>{const a=viewer.toggle();$('autoRotate').classList.toggle('active',a);$('autoRotate').setAttribute('aria-pressed',String(a));};$('viewerDialog').addEventListener('close',()=>{viewer.destroy();trigger?.focus();},{once:true});}catch(e){console.error(e);$('modelCanvas').innerHTML='<div style="display:grid;place-items:center;height:100%;padding:30px;text-align:center">A maquete precisa de suporte a WebGL. Experimente outro navegador.</div>';}}
document.addEventListener('click',e=>{const b=e.target.closest('[data-building]'),p=e.target.closest('[data-place]'),d=e.target.closest('[data-distance]'),a=e.target.closest('[data-action]');if(b){selectBuilding(b.dataset.building);if(b.dataset.connect)connectPlace(b.dataset.connect);}else if(p)selectPlace(p.dataset.place);else if(d)connectPlace(d.dataset.distance);else if(a){if(a.dataset.action==='back')reset();if(a.dataset.action==='viewer')openViewer();}});
document.querySelectorAll('[data-filter]').forEach(btn=>btn.addEventListener('click',()=>{filter=btn.dataset.filter;reset();updateFilter();$('intro').hidden=filter==='places';$('placesList').hidden=filter!=='places';if(filter==='buildings')toast('Selecione um dos quatro prédios para explorar.');}));
$('home').onclick=()=>{filter='all';updateFilter();reset();};$('resetView').onclick=reset;
$('toggle3d').onclick=()=>{if(!ready)return;is3d=!is3d;$('toggle3d').classList.toggle('active',is3d);$('toggle3d').setAttribute('aria-pressed',String(is3d));$('toggle3d').querySelector('b').textContent=is3d?'3D':'2D';map.easeTo({pitch:is3d?55:0,duration:reduced?0:900});};
$('toggleBase').onclick=()=>{if(!ready)return;satellite=!satellite;map.setLayoutProperty('satellite','visibility',satellite?'visible':'none');map.getStyle().layers.filter(l=>l.type==='symbol').forEach(l=>map.setLayoutProperty(l.id,'visibility',satellite?'none':'visible'));$('toggleBase').querySelector('small').textContent=satellite?'Mapa':'Satélite';$('toggleBase').classList.toggle('active',!satellite);};
$('toggleNight').onclick=()=>{if(!ready)return;night=!night;document.body.classList.toggle('night',night);$('toggleNight').setAttribute('aria-pressed',String(night));$('toggleNight').querySelector('[data-icon]').innerHTML=icon(night?'sun':'moon');$('toggleNight').querySelector('small').textContent=night?'Dia':'Noite';map.setPaintProperty('coastal-water','fill-color',night?'#143e52':'#377f89');map.setPaintProperty('satellite','raster-brightness-max',night?.38:1);map.setPaintProperty('satellite','raster-saturation',night?-.55:-.1);map.setLight({anchor:'viewport',color:night?'#b6d4ff':'#ffffff',intensity:night?.35:.5});for(const t of vectorTheme){const color=t.key==='text-color'?'#d0ded7':t.key==='text-halo-color'?'#1d3038':t.key==='fill-extrusion-color'?'#6c8990':t.water?'#193e51':t.key==='line-color'?'#4d6268':t.green?'#243f38':'#253940';map.setPaintProperty(t.id,t.key,night?color:t.value);}};
$('zoomIn').onclick=()=>ready&&map.zoomIn();$('zoomOut').onclick=()=>ready&&map.zoomOut();$('north').onclick=()=>ready&&map.easeTo({bearing:0,duration:reduced?0:700});
$('fullScreen').onclick=async()=>{try{if(document.fullscreenElement)await document.exitFullscreen();else await document.documentElement.requestFullscreen();}catch{toast('Use a opção de tela cheia do seu navegador.');}};
$('collapseCollection').onclick=()=>{const c=$('collection').classList.toggle('collapsed');$('collapseCollection').setAttribute('aria-expanded',String(!c));$('collapseCollection').setAttribute('aria-label',c?'Expandir empreendimentos':'Recolher empreendimentos');};
$('tourButton').onclick=startTour;$('stopTour').onclick=stopTour;$('closeViewer').onclick=()=>$('viewerDialog').close();$('closeInfo').onclick=()=>$('infoDialog').close();$('sourcesButton').onclick=$('infoButton').onclick=()=>$('infoDialog').showModal();
for(const dlg of [$('viewerDialog'),$('infoDialog')]){dlg.addEventListener('click',e=>{if(e.target===dlg){const r=dlg.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)dlg.close();}});}
function handleHash(){const id=location.hash.slice(1);if(buildings.some(b=>b.id===id))selectBuilding(id);else if(places.some(p=>p.id===id))selectPlace(id);}
window.addEventListener('hashchange',handleHash);window.addEventListener('resize',()=>map?.resize());
init();
